<script lang="ts">
 import { onMount } from 'svelte';
 import { features, resources, type Feature } from '$lib/content';
 let tab:'start'|'features'|'check'|'resources'='start';
 let search=''; let filter='all'; let active:Feature=features[0];
 let answers:Record<string,string>={};
 let role='dyrektor';let edition='fundamentals';
 onMount(()=>{try{answers=JSON.parse(localStorage.getItem('cyber-guide-checks')||'{}')}catch{answers={}}});
 $: shown=features.filter(f=>(filter==='all'||f.tier===filter)&&[f.title,f.risk,f.category].join(' ').toLocaleLowerCase('pl').includes(search.toLocaleLowerCase('pl')));
 $: completed=Object.values(answers).filter(v=>v==='done').length;
 function answer(id:string,v:string){answers={...answers,[id]:v};try{localStorage.setItem('cyber-guide-checks',JSON.stringify(answers))}catch{}}
 function printReport(){window.print()}
</script>
<svelte:head><title>Cyberbezpieczna szkoła | Interaktywny poradnik</title><meta name="description" content="Interaktywny przewodnik po zabezpieczeniach szkoły i rozwiązaniach Google for Education."/></svelte:head>
<div class="shell">
<header><div class="brand"><span class="shield">✦</span><div><strong>Cyberbezpieczna szkoła</strong><small>Praktyczny poradnik Google for Education · wersja robocza</small></div></div><span class="status">Projekt do weryfikacji</span></header>
<nav aria-label="Nawigacja główna">
<button class:current={tab==='start'} onclick={()=>tab='start'}>Start</button><button class:current={tab==='features'} onclick={()=>tab='features'}>Zabezpieczenia</button><button class:current={tab==='check'} onclick={()=>tab='check'}>Autodiagnoza</button><button class:current={tab==='resources'} onclick={()=>tab='resources'}>Źródła i kursy</button>
</nav>
<main>
{#if tab==='start'}
<section class="hero"><div class="eyebrow">BEZPIECZEŃSTWO W PRAKTYCE</div><h1>Od wymagania do konkretnego zabezpieczenia.</h1><p>Sprawdź, jak chronić konta, dane i urządzenia w szkole. Dowiedz się, co możesz zrobić w Google Workspace for Education i jak zweryfikować wdrożenie.</p><div class="actions"><button class="primary" onclick={()=>tab='check'}>Rozpocznij autodiagnozę →</button><button class="secondary" onclick={()=>tab='features'}>Poznaj funkcje Google</button></div></section>
<div class="notice"><strong>Ważne:</strong> poradnik jest wersją roboczą. Opisane środki techniczne wspierają bezpieczeństwo, ale nie oznaczają automatycznej zgodności z KSC, NIS2 lub RODO. Zakres obowiązków wymaga odrębnej analizy statusu szkoły i organu prowadzącego.</div>
<div class="tiles"><article><span class="number">01</span><h3>Poznaj zagrożenia</h3><p>Ochrona kont, phishing, dostęp, incydenty i urządzenia.</p></article><article><span class="number">02</span><h3>Sprawdź rozwiązania</h3><p>Funkcje bezpłatne i płatne, instrukcje i źródła Google.</p></article><article><span class="number">03</span><h3>Oceń wdrożenie</h3><p>Zaznacz stan zabezpieczeń i wydrukuj raport.</p></article></div>
<section class="panel"><h2>Dostosuj sposób przeglądania</h2><div class="formgrid"><label>Moja rola<select bind:value={role}><option value="dyrektor">Dyrektor szkoły</option><option value="admin">Administrator IT</option><option value="organ">Organ prowadzący</option><option value="nauczyciel">Nauczyciel</option></select></label><label>Korzystamy z<select bind:value={edition}><option value="fundamentals">Education Fundamentals</option><option value="plus">Education Plus</option><option value="unknown">Nie wiem / nie korzystamy</option></select></label></div><p class="small">Wybór nie jest prawną kwalifikacją szkoły. Nie przesyłamy tych informacji na serwer.</p><button class="primary" onclick={()=>{filter=edition==='plus'?'all':'fundamentals';tab='features'}}>Przeglądaj funkcje →</button></section>
{:else if tab==='features'}
<div class="sectiontitle"><div><div class="eyebrow">KATALOG FUNKCJI</div><h1>Zabezpieczenia Google</h1><p>Wybierz funkcję, aby poznać jej zastosowanie, koszt i czynności po stronie szkoły.</p></div></div>
<div class="filters"><input aria-label="Szukaj" placeholder="Szukaj funkcji lub zagrożenia…" bind:value={search}/><select aria-label="Dostępność" bind:value={filter}><option value="all">Wszystkie funkcje</option><option value="fundamentals">Education Fundamentals</option><option value="plus">Education Plus</option><option value="chromeos">ChromeOS</option></select></div>
<div class="catalog"><div class="entries">{#each shown as f}<button class:selected={active.id===f.id} onclick={()=>active=f}><strong>{f.title}</strong><small>{f.category} · {f.tier==='fundamentals'?'Fundamentals, bez dodatkowej opłaty':f.tier==='plus'?'Zaawansowana licencja płatna':'Zabezpieczenie systemowe'}</small></button>{/each}{#if shown.length===0}<p>Brak wyników.</p>{/if}</div><article class="detail"><span class="tag">{active.tier==='plus'?'Płatna funkcja':active.tier==='fundamentals'?'Fundamentals':'Wbudowane ChromeOS'}</span><h2>{active.title}</h2><h3>Przed czym pomaga chronić?</h3><p>{active.risk}</p><h3>Jak pomaga Google?</h3><p>{active.help}</p><h3>Co powinna zrobić szkoła?</h3><ol>{#each active.steps as step}<li>{step}</li>{/each}</ol><h3>Powiązanie z przepisami</h3><p>{active.legal}</p><p class="small">Powiązanie informacyjne, nie certyfikacja zgodności z określonym przepisem.</p><a href={active.link} target="_blank" rel="noopener noreferrer">Oficjalna dokumentacja: {active.source} ↗</a><div class="answer"><strong>Stan w naszej szkole</strong><select value={answers[active.id]||'unknown'} onchange={e=>answer(active.id,e.currentTarget.value)}><option value="unknown">Nie sprawdzono</option><option value="done">Wdrożone i sprawdzone</option><option value="todo">Do wdrożenia</option><option value="na">Nie dotyczy</option></select></div></article></div>
{:else if tab==='check'}
<div class="eyebrow">SAMOOCENA</div><h1>Sprawdź stan zabezpieczeń</h1><p>Oceń wyłącznie te funkcje, których stosowanie jest uzasadnione w Twojej szkole. Odpowiedzi zapisują się lokalnie w tej przeglądarce.</p><div class="summary"><strong>{completed} / {features.length}</strong><span>funkcji oznaczonych jako wdrożone i sprawdzone</span></div><div class="progress"><div style:width={100*completed/features.length+'%'}></div></div>
<div class="checklist">{#each features as f}<div class="checkrow"><div><strong>{f.title}</strong><small>{f.risk}</small></div><select aria-label={'Stan '+f.title} value={answers[f.id]||'unknown'} onchange={e=>answer(f.id,e.currentTarget.value)}><option value="unknown">Nie wiem / nie sprawdzono</option><option value="done">Wdrożone i sprawdzone</option><option value="todo">Wymaga działania</option><option value="na">Nie dotyczy</option></select></div>{/each}</div><div class="actions"><button class="primary" onclick={printReport}>Drukuj / Zapisz jako PDF</button><button class="secondary" onclick={()=>tab='features'}>Otwórz instrukcje</button></div><p class="small">Wynik nie jest audytem prawnym ani automatycznym testem konfiguracji Google Workspace.</p>
{:else}
<div class="eyebrow">MATERIAŁY ŹRÓDŁOWE</div><h1>Oficjalne dokumenty i szkolenia</h1><p>Bezpośrednie odnośniki do Google i polskiego publikatora prawa.</p><div class="resourcegrid">{#each resources as r}<article><small>{r.access}</small><h2>{r.title}</h2><p>{r.detail}</p><a target="_blank" rel="noopener noreferrer" href={r.url}>Otwórz źródło ↗</a></article>{/each}</div>
{/if}
</main><footer><strong>Cyberbezpieczna szkoła</strong><span>Wersja demonstracyjna · treści wymagają końcowej weryfikacji prawnej i produktowej przed publikacją przez MEN lub Google.</span></footer></div>
<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#f5f7fb;color:#17243d;font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}:global(button),:global(select),:global(input){font:inherit}:global(button){cursor:pointer}.shell{max-width:1200px;margin:auto;padding:0 24px}header{display:flex;justify-content:space-between;align-items:center;padding:25px 0;border-bottom:1px solid #e4e8ef}.brand{display:flex;align-items:center;gap:12px}.brand strong,.brand small{display:block}.brand strong{font-size:19px}.brand small{font-size:12px;color:#69768b;margin-top:3px}.shield{display:grid;place-items:center;background:#1b66cc;border-radius:13px;width:46px;height:46px;color:#fff;font-size:30px}.status,.tag{font-size:12px;border-radius:999px;background:#e8f0fe;color:#2153a3;padding:8px 12px}nav{display:flex;gap:7px;border-bottom:1px solid #e4e8ef;padding:12px 0;overflow:auto}nav button{border:0;background:transparent;color:#55647a;padding:12px 17px;border-radius:9px;white-space:nowrap}nav button.current{background:#e6efff;color:#1756b9;font-weight:700}main{padding:38px 0 70px;min-height:65vh}h1{font-size:clamp(30px,4vw,48px);line-height:1.12;letter-spacing:-1.5px;margin:12px 0 17px}h2{font-size:22px;letter-spacing:-.5px}h3{font-size:15px;margin:24px 0 8px}p{line-height:1.65;color:#596982}.hero{background:linear-gradient(120deg,#eaf2ff,#fff);border:1px solid #dfe9f8;padding:48px;border-radius:22px;max-width:100%}.hero h1{max-width:720px}.hero p{max-width:680px;font-size:17px}.eyebrow{font-weight:800;color:#2863b8;letter-spacing:2px;font-size:12px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.primary,.secondary{border-radius:9px;padding:13px 18px;font-weight:700;border:1px solid #1c5ebd}.primary{background:#1c5ebd;color:white}.secondary{background:white;color:#2058aa}.notice{padding:18px 22px;border-left:4px solid #e0a32b;background:#fff9e9;margin:24px 0;color:#715829;line-height:1.6}.tiles,.resourcegrid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.tiles article,.resourcegrid article,.panel,.detail{background:white;border:1px solid #e2e7ef;border-radius:15px;padding:24px}.number{font-size:13px;color:#2162b5;font-weight:800}.panel{margin-top:24px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.formgrid label{font-weight:700;font-size:14px}.formgrid select{display:block;margin:9px 0 15px;width:100%}.small{font-size:12px;color:#69768b}select,input{background:white;border:1px solid #cbd5e1;border-radius:9px;padding:12px;color:#24324c}.filters{display:flex;gap:12px;margin:24px 0}.filters input{flex:1}.catalog{display:grid;grid-template-columns:330px 1fr;gap:20px}.entries{display:flex;flex-direction:column;gap:8px}.entries button{text-align:left;border:1px solid #dfe5ef;border-radius:12px;padding:17px;background:white;color:#192c47}.entries button.selected{background:#e9f2ff;border-color:#3182d9}.entries small,.checkrow small{display:block;font-size:12px;color:#708198;margin-top:7px;line-height:1.5}.detail ol{line-height:1.8;color:#53657c;padding-left:21px}.detail a,.resourcegrid a{color:#175ebf;font-weight:700;text-decoration:none}.answer{display:flex;justify-content:space-between;align-items:center;background:#f1f6fd;border-radius:10px;padding:14px;margin-top:25px;gap:12px}.summary{display:flex;align-items:center;gap:15px;background:#e8f0ff;border-radius:12px;padding:22px;margin:24px 0 12px}.summary strong{font-size:29px}.progress{height:9px;background:#e1e8f2;border-radius:99px;overflow:hidden}.progress div{height:100%;background:#2b73d2}.checklist{margin-top:20px}.checkrow{display:flex;justify-content:space-between;align-items:center;padding:17px 12px;border-bottom:1px solid #dfe6f0;gap:15px}.resourcegrid article{min-height:210px}.resourcegrid small{color:#2869a9;font-weight:700}footer{border-top:1px solid #e1e8f0;padding:26px 0;display:flex;justify-content:space-between;gap:20px;color:#69768b;font-size:12px}footer strong{color:#17243d}@media(max-width:720px){.shell{padding:0 14px}header{align-items:flex-start;gap:8px}.status{display:none}.hero{padding:25px}.tiles,.resourcegrid,.formgrid,.catalog{grid-template-columns:1fr}.filters,.answer,.checkrow,footer{flex-direction:column;align-items:stretch}.catalog{gap:13px}main{padding-top:25px}}@media print{header,nav,.actions,.filters,footer,.entries,.notice{display:none!important}body{background:white}.shell{max-width:none}.catalog{display:block}}
</style>